'use strict';

/**
* BLAS level 2 routine to solve one of the systems of equations `A*x = b` or `A^T*x = b` or `A^H*x = b`, where `b` and `x` are `N` element vector and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix, supplied in packed form.
*
* @module @stdlib/blas/base/ztpsv
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var ztpsv = require( '@stdlib/blas/base/ztpsv' );
*
* var AP = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 4.0, 4.0, 3.0, 3.0, 5.0, 5.0, 6.0, 6.0 ] );
* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 20.0, 0.0, 62.0 ] );
*
* ztpsv( 'row-major', 'lower', 'no-transpose', 'non-unit', 3, AP, x, 1 );
* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var ztpsv = require( '@stdlib/blas/base/ztpsv' );
*
* var AP = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 4.0, 4.0, 3.0, 3.0, 5.0, 5.0, 6.0, 6.0 ] );
* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 20.0, 0.0, 62.0 ] );
*
* ztpsv.ndarray( 'row-major', 'lower', 'no-transpose', 'non-unit', 3, AP, 1, 0, x, 1, 0 );
* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var ztpsv;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	ztpsv = main;
} else {
	ztpsv = tmp;
}


// EXPORTS //

module.exports = ztpsv;

// exports: { "ndarray": "ztpsv.ndarray" }
